const CARDS = [{"id":0,"name":"The Fool","en":"THE FOOL","roman":"0","archetype":"explorer","emotion":"curious","symbols":[{"name":"Cliff","meaning":"the unknown and its boundaries","x":"50","y":"63"},{"name":"White rose","meaning":"starting with an open heart","x":"60","y":"37"},{"name":"Small dog","meaning":"companionship and a reminder to stay aware","x":"65","y":"75"}],"theme":"Beginnings","reverse":"Impulsiveness or hesitation","action":"Make room for an idea you have not started yet.","category":"Major Arcana","order":0,"observation":"A young person stands near a cliff with a bundle, a rose and a small dog.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M00","reverseAction":"If the basics are ready but fear of mistakes stops you, try one small step. If you are unprepared, meet the essential conditions first."},{"id":1,"name":"The Magician","en":"THE MAGICIAN","roman":"I","archetype":"creator","emotion":"focused","symbols":[{"name":"Raised hand","meaning":"connecting an idea to action","x":"52","y":"19"},{"name":"Tools on the table","meaning":"resources you already have","x":"48","y":"62"},{"name":"Infinity sign","meaning":"potential that keeps evolving","x":"50","y":"9"}],"theme":"Action","reverse":"Scattered resources","action":"Use one resource you already have to make a small first piece.","category":"Major Arcana","order":1,"observation":"One hand raises a wand to the sky, the other points down; tools from all four suits rest on a table.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M01","reverseAction":"Having tools without a draft may suggest difficulty starting. If you have finished and only lack feedback, do not interpret this as inability."},{"id":2,"name":"Strength","en":"STRENGTH","roman":"VIII","archetype":"gentle guide","emotion":"gentle","symbols":[{"name":"Lion","meaning":"instinct and strong feelings","x":"58","y":"65"},{"name":"Hands","meaning":"gentle strength","x":"52","y":"49"},{"name":"Flower garland","meaning":"patience and vitality","x":"45","y":"25"}],"theme":"Acceptance","reverse":"Self-doubt","action":"Respond gently to a strong emotion.","category":"Major Arcana","order":8,"observation":"A woman interacts with a lion beneath an infinity sign, with flowers around them.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M08","reverseAction":"If persistence comes with recorded fatigue, adjust your effort instead of suppressing your feelings."},{"id":3,"name":"The Hermit","en":"THE HERMIT","roman":"IX","archetype":"seeker","emotion":"quiet","symbols":[{"name":"Lantern","meaning":"light for the next step","x":"64","y":"25"},{"name":"Staff","meaning":"support that steadies you","x":"64","y":"57"},{"name":"Mountain peak","meaning":"solitude and perspective","x":"48","y":"83"}],"theme":"Reflection","reverse":"Isolation or withdrawal","action":"Give yourself quiet time to observe.","category":"Major Arcana","order":9,"observation":"A figure on high ground holds a lantern with a star inside.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M09","reverseAction":"If solitude no longer helps, ask a trusted person one specific question."},{"id":4,"name":"The Hanged Man","en":"THE HANGED MAN","roman":"XII","archetype":"observer","emotion":"paused","symbols":[{"name":"Upside-down posture","meaning":"looking from another angle","x":"50","y":"55"},{"name":"Halo","meaning":"insight found in a pause","x":"50","y":"81"},{"name":"Crossed legs","meaning":"breaking a familiar pattern","x":"52","y":"39"}],"theme":"A different perspective","reverse":"Difficulty releasing control","action":"Write the problem from someone else's perspective.","category":"Major Arcana","order":12,"observation":"A person hangs upside down from a leafy frame, with a halo and bent legs.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M12","reverseAction":"If waiting brings no new information or deadline, agree on the next check-in."},{"id":5,"name":"The Star","en":"THE STAR","roman":"XVII","archetype":"healer","emotion":"hopeful","symbols":[{"name":"Starlight","meaning":"a direction for your hopes","x":"49","y":"16"},{"name":"Flowing water","meaning":"letting feelings move again","x":"63","y":"62"},{"name":"Land","meaning":"bringing hope into everyday life","x":"30","y":"78"}],"theme":"Recovery","reverse":"Hope temporarily obscured","action":"Record one small thing you still believe in.","category":"Major Arcana","order":17,"observation":"Large and small stars shine above a figure pouring water from two vessels, with a bird nearby.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M17","reverseAction":"If hope lacks tools, company or rest, add one concrete form of support."},{"id":6,"name":"The Moon","en":"THE MOON","roman":"XVIII","archetype":"dreamer","emotion":"uncertain","symbols":[{"name":"Moon","meaning":"uncertainty and intuition","x":"51","y":"19"},{"name":"Path","meaning":"a journey through the unknown","x":"49","y":"66"},{"name":"Two towers","meaning":"the boundary between familiar and unfamiliar","x":"77","y":"39"}],"theme":"Feelings","reverse":"Inner confusion","action":"Separate observed facts from imagined possibilities.","category":"Major Arcana","order":18,"observation":"The moon shines over a path, towers, a dog, a wolf and a creature emerging from water.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M18","reverseAction":"New facts may explain some worries. Keep the rest uncertain rather than declaring every guess correct."},{"id":7,"name":"The Sun","en":"THE SUN","roman":"XIX","archetype":"storyteller","emotion":"joyful","symbols":[{"name":"Sun","meaning":"clarity and vitality","x":"50","y":"21"},{"name":"Child","meaning":"honest and free expression","x":"47","y":"65"},{"name":"Sunflowers","meaning":"growth and response","x":"76","y":"47"}],"theme":"Expression","reverse":"Difficulty allowing joy","action":"Share something that makes you feel alive.","category":"Major Arcana","order":19,"observation":"A child rides a white horse beneath the sun, carrying a red banner.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M19","reverseAction":"Finishing a task while tired may call for rest rather than forced excitement."},{"id":8,"name":"The High Priestess","en":"THE HIGH PRIESTESS","roman":"2","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Observation, missing information and inner understanding","x":50,"y":50,"scene":true}],"theme":"Observation, missing information and inner understanding","reverse":"Ignoring inner questions or treating unknowns as conclusions","action":"Separate what is known from what is unknown and check key information.","category":"Major Arcana","order":2,"observation":"Black and white pillars frame a figure with a partly covered scroll, a crescent moon and a veil.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M02","reverseAction":"A fact needs checking; intuition should not replace verification."},{"id":9,"name":"The Empress","en":"THE EMPRESS","roman":"3","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Nurturing, creativity and conditions for growth","x":50,"y":50,"scene":true}],"theme":"Nurturing, creativity and conditions for growth","reverse":"Insufficient support or exhaustion from over-caring","action":"Give a piece of work time, space or care.","category":"Major Arcana","order":3,"observation":"A figure wears a star crown near a Venus symbol, crops and water.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M03","reverseAction":"Care alone may not supply enough time, space or feedback. Check the specific conditions."},{"id":10,"name":"The Emperor","en":"THE EMPEROR","roman":"4","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Structure, responsibility and boundaries","x":50,"y":50,"scene":true}],"theme":"Structure, responsibility and boundaries","reverse":"Loose structure or rigid rules","action":"Clarify roles, scope and decision rules.","category":"Major Arcana","order":4,"observation":"A throne with ram-head decorations supports a figure holding a scepter and an orb.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M04","reverseAction":"Unclear roles can block progress. Refusing to adjust established roles is a different imbalance."},{"id":11,"name":"The Hierophant","en":"THE HIEROPHANT","roman":"5","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Tradition, shared standards and guidance","x":50,"y":50,"scene":true}],"theme":"Tradition, shared standards and guidance","reverse":"Unsuitable guidance or questioning old standards","action":"Review a learning method and ask someone experienced.","category":"Major Arcana","order":5,"observation":"A crowned figure makes a blessing gesture above keys and two other figures.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M05","reverseAction":"Compare the course requirements with your goals and decide where the method applies."},{"id":12,"name":"The Lovers","en":"THE LOVERS","roman":"6","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Relationships, mutual recognition and values","x":50,"y":50,"scene":true}],"theme":"Relationships, mutual recognition and values","reverse":"Different values or expectations, or an unmade commitment","action":"Check both people's wishes and the choice you are willing to make.","category":"Major Arcana","order":6,"observation":"Two figures stand beneath an angel, with trees behind them.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M06","reverseAction":"Different stated goals need discussion; attraction does not prove agreement."},{"id":13,"name":"The Chariot","en":"THE CHARIOT","roman":"7","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Progress, coordination and direction","x":50,"y":50,"scene":true}],"theme":"Progress, coordination and direction","reverse":"Scattered direction or an uncoordinated pace","action":"Choose one goal and coordinate your resources.","category":"Major Arcana","order":7,"observation":"A decorated figure stands in a chariot behind two sphinxes.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M07","reverseAction":"Two tasks competing for the same time need a clear priority."},{"id":14,"name":"Wheel of Fortune","en":"WHEEL OF FORTUNE","roman":"10","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Change, cycles and shifting conditions","x":50,"y":50,"scene":true}],"theme":"Change, cycles and shifting conditions","reverse":"Resisting change or adjusting your response","action":"Check which parts of your plan need updating.","category":"Major Arcana","order":10,"observation":"A wheel is surrounded by creatures at the four corners.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M10","reverseAction":"If conditions changed but the plan did not, update it; this does not mean permanent bad luck."},{"id":15,"name":"Justice","en":"JUSTICE","roman":"11","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Fairness, evidence, responsibility and consequences","x":50,"y":50,"scene":true}],"theme":"Fairness, evidence, responsibility and consequences","reverse":"Insufficient evidence, inconsistent standards or reviewing a judgment","action":"Check facts, agreements and shared responsibilities.","category":"Major Arcana","order":11,"observation":"A figure sits between two pillars.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M11","reverseAction":"Align the standards if two people judge the same event differently."},{"id":16,"name":"Death","en":"DEATH","roman":"13","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Endings, letting go and transformation","x":50,"y":50,"scene":true}],"theme":"Endings, letting go and transformation","reverse":"Reluctance to end a phase or an ongoing transition","action":"Confirm what has ended and arrange a handover.","category":"Major Arcana","order":13,"observation":"A rider carries a black flag with a rose, among figures from different walks of life.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M13","reverseAction":"If an old arrangement no longer fits, identify a practical way to finish and hand over."},{"id":17,"name":"Temperance","en":"TEMPERANCE","roman":"14","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Integration, coordination and a sustainable pace","x":50,"y":50,"scene":true}],"theme":"Integration, coordination and a sustainable pace","reverse":"An uneven rhythm or an untested approach to balance","action":"Adjust roles or pace and try one small change.","category":"Major Arcana","order":14,"observation":"An angel pours between two cups, with one foot on land and one in water.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M14","reverseAction":"Accommodating every arrangement can overload you. Reduce commitments rather than only aiming for balance."},{"id":18,"name":"The Devil","en":"THE DEVIL","roman":"15","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Attachment, desire and cycles of limitation","x":50,"y":50,"scene":true}],"theme":"Attachment, desire and cycles of limitation","reverse":"Recognizing an attachment or struggling to change a pattern","action":"Identify a hard-to-release habit and its cost.","category":"Major Arcana","order":15,"observation":"A devil appears with a torch and two connected figures.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M15","reverseAction":"Noticing an unhelpful habit is a start; look for an alternative you can actually practice."},{"id":19,"name":"The Tower","en":"THE TOWER","roman":"16","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Disrupted structures and re-examination","x":50,"y":50,"scene":true}],"theme":"Disrupted structures and re-examination","reverse":"Avoiding a structural problem or rebuilding after disruption","action":"Confirm the facts, then address an arrangement that no longer works.","category":"Major Arcana","order":16,"observation":"A damaged tower stands above falling figures.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M16","reverseAction":"Check which specific rule failed when warning signs appear; do not assume everything is wrong."},{"id":20,"name":"Judgement","en":"JUDGEMENT","roman":"20","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Review, renewed response and change","x":50,"y":50,"scene":true}],"theme":"Review, renewed response and change","reverse":"Hesitating to respond or judging yourself too soon","action":"Use experience to decide what to keep or change.","category":"Major Arcana","order":20,"observation":"An angel sounds a trumpet above a flag and rising figures.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M20","reverseAction":"After specific feedback, begin with one small revision if you have not decided how to adjust."},{"id":21,"name":"The World","en":"THE WORLD","roman":"21","archetype":"traveler","emotion":"exploratory","symbols":[{"name":"Card scene","meaning":"Integration, completion and new boundaries","x":50,"y":50,"scene":true}],"theme":"Integration, completion and new boundaries","reverse":"Unfinished closure or uncertainty after completion","action":"Define completion, organize the result and choose a next step.","category":"Major Arcana","order":21,"observation":"A central figure is surrounded by a wreath-like structure.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-M21","reverseAction":"Core work may be finished while review or handover remains; near completion is not the same as completion."},{"id":22,"name":"Ace of Wands","en":"ACE OF WANDS","roman":"1","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Starting, creativity and energy","x":50,"y":50,"scene":true}],"theme":"Starting, creativity and energy","reverse":"Low starting energy or enthusiasm without action","action":"Make a small sample to test the idea.","category":"Wands","order":22,"observation":"A hand holds a sprouting wand.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W01","reverseAction":"If there is an idea but no time, schedule one short practice session."},{"id":23,"name":"Two of Wands","en":"TWO OF WANDS","roman":"2","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Planning and a wider perspective","x":50,"y":50,"scene":true}],"theme":"Planning and a wider perspective","reverse":"A plan that is hard to execute or an unclear scope","action":"Compare the conditions of two possible routes.","category":"Wands","order":23,"observation":"A figure holds a globe and looks into the distance.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W02","reverseAction":"If you compare many routes without criteria, list two practical conditions first."},{"id":24,"name":"Three of Wands","en":"THREE OF WANDS","roman":"3","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Waiting after action and expanding possibilities","x":50,"y":50,"scene":true}],"theme":"Waiting after action and expanding possibilities","reverse":"Delayed feedback or insufficient conditions for expansion","action":"Track feedback from your first attempt.","category":"Wands","order":24,"observation":"A figure watches ships at sea.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W03","reverseAction":"After submitting work, distinguish patient waiting from a need to follow up."},{"id":25,"name":"Four of Wands","en":"FOUR OF WANDS","roman":"4","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Celebration, belonging and a stable milestone","x":50,"y":50,"scene":true}],"theme":"Celebration, belonging and a stable milestone","reverse":"Limited belonging or a result that needs maintenance","action":"Confirm a shared achievement with your companions.","category":"Wands","order":25,"observation":"A garland hangs above figures holding flowers near buildings.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W04","reverseAction":"A celebration does not replace clear roles and follow-up arrangements."},{"id":26,"name":"Five of Wands","en":"FIVE OF WANDS","roman":"5","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Competition, disagreement and coordination","x":50,"y":50,"scene":true}],"theme":"Competition, disagreement and coordination","reverse":"Suppressed differences or easing conflict","action":"Define the shared task before dividing roles.","category":"Wands","order":26,"observation":"Several people raise crossing wands.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W05","reverseAction":"Silence may hide unheard views; check whether actual discussion has taken place."},{"id":27,"name":"Six of Wands","en":"SIX OF WANDS","roman":"6","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Recognition and public achievement","x":50,"y":50,"scene":true}],"theme":"Recognition and public achievement","reverse":"Recognition delayed or dependence on outside approval","action":"Share the result and thank collaborators.","category":"Wands","order":27,"observation":"A rider raises a wand decorated with a wreath.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W06","reverseAction":"If work is finished without public feedback, define your own completion criteria first."},{"id":28,"name":"Seven of Wands","en":"SEVEN OF WANDS","roman":"7","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Holding your ground and meeting challenges","x":50,"y":50,"scene":true}],"theme":"Holding your ground and meeting challenges","reverse":"Difficulty holding a position or excessive opposition","action":"Explain why a standard matters to you.","category":"Wands","order":28,"observation":"A figure on high ground faces several wands.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W07","reverseAction":"Separate what must be protected from what can be negotiated before immediately disagreeing."},{"id":29,"name":"Eight of Wands","en":"EIGHT OF WANDS","roman":"8","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Momentum, messages and rapid change","x":50,"y":50,"scene":true}],"theme":"Momentum, messages and rapid change","reverse":"Blocked progress or confusion caused by speed","action":"Focus on tasks whose requirements are already clear.","category":"Wands","order":29,"observation":"Wands fly across an open landscape.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W08","reverseAction":"If a message lacks key details, supply them rather than sending faster reminders."},{"id":30,"name":"Nine of Wands","en":"NINE OF WANDS","roman":"9","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Resilience, vigilance and a final check","x":50,"y":50,"scene":true}],"theme":"Resilience, vigilance and a final check","reverse":"Exhaustion or vigilance that blocks support","action":"Keep one useful check and make time to rest.","category":"Wands","order":30,"observation":"A bandaged figure guards a row of wands.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W09","reverseAction":"After prolonged alertness, review whether you have enough rest and trustworthy support."},{"id":31,"name":"Ten of Wands","en":"TEN OF WANDS","roman":"10","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Burden, responsibility and overload","x":50,"y":50,"scene":true}],"theme":"Burden, responsibility and overload","reverse":"Releasing a burden or difficulty sharing responsibility","action":"Redistribute the workload.","category":"Wands","order":31,"observation":"A figure carries a large bundle of wands.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W10","reverseAction":"Recognizing overload is not enough; decide which task to postpone or hand over."},{"id":32,"name":"Page of Wands","en":"PAGE OF WANDS","roman":"11","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Curiosity about ideas and trying to express them","x":50,"y":50,"scene":true}],"theme":"Curiosity about ideas and trying to express them","reverse":"Untested ideas or novelty replacing commitment","action":"Make one small sample.","category":"Wands","order":32,"observation":"A young figure holds an upright, sprouting wand with both hands, with sand and hills behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W11","reverseAction":"Many new ideas without a single attempt may call for a small practical trial."},{"id":33,"name":"Knight of Wands","en":"KNIGHT OF WANDS","roman":"12","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Energetic action, risk and speed","x":50,"y":50,"scene":true}],"theme":"Energetic action, risk and speed","reverse":"Uncoordinated impulses or interrupted enthusiasm","action":"Move forward with one clearly defined step.","category":"Wands","order":33,"observation":"An armored rider holds a wand as the horse lifts its front legs, with sand and hills behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W12","reverseAction":"Finish a current step and follow its feedback before changing direction again."},{"id":34,"name":"Queen of Wands","en":"QUEEN OF WANDS","roman":"13","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Confidence, creative space and encouragement","x":50,"y":50,"scene":true}],"theme":"Confidence, creative space and encouragement","reverse":"Low confidence or encouragement that overlooks others' needs","action":"Encourage a companion to express a creative idea.","category":"Wands","order":34,"observation":"A queen holds a wand and a sunflower on a throne, with a black cat at her feet.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W13","reverseAction":"Trying to lift the mood may miss a companion's difficulties; make room to listen."},{"id":35,"name":"King of Wands","en":"KING OF WANDS","roman":"14","archetype":"doer","emotion":"passionate","symbols":[{"name":"Card scene","meaning":"Organizing a vision and taking responsibility for progress","x":50,"y":50,"scene":true}],"theme":"Organizing a vision and taking responsibility for progress","reverse":"An unorganized vision or overly dominant leadership","action":"Give the vision a scope and clear roles.","category":"Wands","order":35,"observation":"A king holds a sprouting wand on a throne decorated with lions.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-W14","reverseAction":"A clear goal still needs roles and space for others to propose different methods."},{"id":36,"name":"Ace of Cups","en":"ACE OF CUPS","roman":"1","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Opening to feelings and acceptance","x":50,"y":50,"scene":true}],"theme":"Opening to feelings and acceptance","reverse":"Difficulty expressing feelings or a need for self-care","action":"Name a new feeling and allow its expression.","category":"Cups","order":36,"observation":"A hand emerges from a cloud holding a cup, with water flowing down.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C01","reverseAction":"If you feel moved but cannot express it, first identify what you actually need."},{"id":37,"name":"Two of Cups","en":"TWO OF CUPS","roman":"2","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Exchange, mutual recognition and cooperation","x":50,"y":50,"scene":true}],"theme":"Exchange, mutual recognition and cooperation","reverse":"Unequal communication or agreement not yet confirmed","action":"Confirm both people's intentions and agreements.","category":"Cups","order":37,"observation":"Two people raise cups toward each other, beneath a staff and a lion's head.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C02","reverseAction":"If a promise means different things to each person, confirm its scope again."},{"id":38,"name":"Three of Cups","en":"THREE OF CUPS","roman":"3","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Sharing, support and celebration together","x":50,"y":50,"scene":true}],"theme":"Sharing, support and celebration together","reverse":"Insufficient support or group activity hiding personal needs","action":"Invite friends to share a milestone.","category":"Cups","order":38,"observation":"Three people raise cups with fruit around them.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C03","reverseAction":"Frequent gatherings without a response to a specific request are different from practical support."},{"id":39,"name":"Four of Cups","en":"FOUR OF CUPS","roman":"4","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Weariness, pausing and responding to opportunity","x":50,"y":50,"scene":true}],"theme":"Weariness, pausing and responding to opportunity","reverse":"Beginning to respond or remaining weary","action":"Distinguish a need for rest from reluctance to accept.","category":"Cups","order":39,"observation":"A seated figure faces three cups while another cup is offered.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C04","reverseAction":"A small invitation may become possible; if you are still tired, rest can come first."},{"id":40,"name":"Five of Cups","en":"FIVE OF CUPS","roman":"5","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Loss and remaining resources","x":50,"y":50,"scene":true}],"theme":"Loss and remaining resources","reverse":"Noticing support again or difficulty processing loss","action":"Acknowledge the loss, then identify what remains.","category":"Cups","order":40,"observation":"A figure looks at fallen cups, with upright cups behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C05","reverseAction":"Naming a remaining resource does not require denying what was lost."},{"id":41,"name":"Six of Cups","en":"SIX OF CUPS","roman":"6","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Memory, familiar support and giving","x":50,"y":50,"scene":true}],"theme":"Memory, familiar support and giving","reverse":"Being held by the past or updating old impressions","action":"Draw on an experience that helped before.","category":"Cups","order":41,"observation":"Two people exchange cups filled with flowers.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C06","reverseAction":"An old experience can help, but record how today's conditions differ."},{"id":42,"name":"Seven of Cups","en":"SEVEN OF CUPS","roman":"7","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Imagination, options and discernment","x":50,"y":50,"scene":true}],"theme":"Imagination, options and discernment","reverse":"Narrowing options or confusing wishes with feasible conditions","action":"List verified conditions separately from imagined ones.","category":"Cups","order":42,"observation":"A figure faces cups holding different images in the clouds.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C07","reverseAction":"Check the time and resources needed for one option among many wishes."},{"id":43,"name":"Eight of Cups","en":"EIGHT OF CUPS","roman":"8","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Leaving an unfulfilling situation and searching","x":50,"y":50,"scene":true}],"theme":"Leaving an unfulfilling situation and searching","reverse":"Hesitation about leaving or a need to settle after departure","action":"Clarify why you want to leave and what comes next.","category":"Cups","order":43,"observation":"A figure leaves arranged cups and walks toward mountains.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C08","reverseAction":"Without an alternative plan, distinguish temporary fatigue from a long-term mismatch."},{"id":44,"name":"Nine of Cups","en":"NINE OF CUPS","roman":"9","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Satisfaction, wishes and personal enjoyment","x":50,"y":50,"scene":true}],"theme":"Satisfaction, wishes and personal enjoyment","reverse":"Limited satisfaction or discovering another need after success","action":"Name one need that has been met.","category":"Cups","order":44,"observation":"A figure sits before nine arranged cups.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C09","reverseAction":"If an expected result does not satisfy you, identify what is still missing."},{"id":45,"name":"Ten of Cups","en":"TEN OF CUPS","roman":"10","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Shared contentment and belonging","x":50,"y":50,"scene":true}],"theme":"Shared contentment and belonging","reverse":"Different expectations or an ideal image overriding real relationships","action":"Bring a shared vision into one concrete interaction.","category":"Cups","order":45,"observation":"Cups form a rainbow above adults and children.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C10","reverseAction":"Discuss practical arrangements when harmony means different things to each person."},{"id":46,"name":"Page of Cups","en":"PAGE OF CUPS","roman":"11","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"New feelings and unexpected inspiration","x":50,"y":50,"scene":true}],"theme":"New feelings and unexpected inspiration","reverse":"Unclear feelings or inspiration without action","action":"Identify a new feeling.","category":"Cups","order":46,"observation":"A young figure stands by water holding a cup with a fish inside.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C11","reverseAction":"Record a new idea, clarify its details and try something small."},{"id":47,"name":"Knight of Cups","en":"KNIGHT OF CUPS","roman":"12","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Pursuing ideals and expressing affection","x":50,"y":50,"scene":true}],"theme":"Pursuing ideals and expressing affection","reverse":"Words and actions that differ or excessive idealization","action":"Make an invitation clear and confirm the other person's wishes.","category":"Cups","order":47,"observation":"A rider on a white horse holds a cup and wears a winged helmet.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C12","reverseAction":"An attractive promise still needs a clear scope and practical arrangements."},{"id":48,"name":"Queen of Cups","en":"QUEEN OF CUPS","roman":"13","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Listening, understanding and emotional care","x":50,"y":50,"scene":true}],"theme":"Listening, understanding and emotional care","reverse":"Uneven emotional care or rebuilding boundaries","action":"Listen fully before responding.","category":"Cups","order":48,"observation":"A queen sits by water and holds a covered cup with both hands.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C13","reverseAction":"Continually listening to others can leave your own energy and requests overlooked."},{"id":49,"name":"King of Cups","en":"KING OF CUPS","roman":"14","archetype":"feeler","emotion":"tender","symbols":[{"name":"Card scene","meaning":"Coordinating feelings and responding steadily","x":50,"y":50,"scene":true}],"theme":"Coordinating feelings and responding steadily","reverse":"Difficulty staying steady or excessive suppression of feelings","action":"Consider feelings alongside task arrangements.","category":"Cups","order":49,"observation":"A king sits on a throne amid water, holding a cup and a short scepter, with a ship and a leaping dolphin behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-C14","reverseAction":"To preserve peace, you may leave real differences unspoken; begin with specific facts."},{"id":50,"name":"Ace of Swords","en":"ACE OF SWORDS","roman":"1","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Clarity, judgment and getting to the core","x":50,"y":50,"scene":true}],"theme":"Clarity, judgment and getting to the core","reverse":"Unclear judgment or overly sharp expression","action":"Write the core question and its evidence.","category":"Swords","order":50,"observation":"A hand raises a sword topped with a crown and leaves.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S01","reverseAction":"If evidence is incomplete, list what needs checking before claiming one answer."},{"id":51,"name":"Two of Swords","en":"TWO OF SWORDS","roman":"2","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Stalemate, pausing and missing information","x":50,"y":50,"scene":true}],"theme":"Stalemate, pausing and missing information","reverse":"A loosening stalemate or difficulty choosing","action":"Add one key fact before choosing.","category":"Swords","order":51,"observation":"A blindfolded figure holds crossed swords with water behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S02","reverseAction":"After new information arrives, compare options and explain their costs."},{"id":52,"name":"Three of Swords","en":"THREE OF SWORDS","roman":"3","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Pain, disappointment and difficult facts","x":50,"y":50,"scene":true}],"theme":"Pain, disappointment and difficult facts","reverse":"Processing pain or avoiding a difficult truth","action":"Acknowledge hurt and name its specific cause.","category":"Swords","order":52,"observation":"Three swords pierce a heart beneath rain.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S03","reverseAction":"Being able to discuss disappointment does not mean recovery is complete; allow time."},{"id":53,"name":"Four of Swords","en":"FOUR OF SWORDS","roman":"4","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Rest, recovery and a pause in thinking","x":50,"y":50,"scene":true}],"theme":"Rest, recovery and a pause in thinking","reverse":"Difficulty resting or readiness to resume gradually","action":"Take a short pause before returning to the discussion.","category":"Swords","order":53,"observation":"A figure lies indoors with swords hanging above and resting nearby.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S04","reverseAction":"Choose according to your actual energy: interrupted rest differs from readiness for a small task."},{"id":54,"name":"Five of Swords","en":"FIVE OF SWORDS","roman":"5","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Cost, conflict and an empty victory","x":50,"y":50,"scene":true}],"theme":"Cost, conflict and an empty victory","reverse":"Wanting to end a conflict or unresolved costs","action":"Check whether the argument harms a shared goal.","category":"Swords","order":54,"observation":"A figure gathers swords in the foreground while others leave.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S05","reverseAction":"An argument may stop while trust and shared responsibilities still need repair."},{"id":55,"name":"Six of Swords","en":"SIX OF SWORDS","roman":"6","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Transition, movement and carrying unresolved problems","x":50,"y":50,"scene":true}],"theme":"Transition, movement and carrying unresolved problems","reverse":"A blocked transition or old issues that still need attention","action":"Seek help and leave a difficult situation gradually.","category":"Swords","order":55,"observation":"A boat carries people and swords across water.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S06","reverseAction":"Changing the setting may not solve the same communication problem; adjust the approach."},{"id":56,"name":"Seven of Swords","en":"SEVEN OF SWORDS","roman":"7","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Strategy, secrecy or independent arrangements","x":50,"y":50,"scene":true}],"theme":"Strategy, secrecy or independent arrangements","reverse":"A strategy that needs openness or the costs of concealment","action":"Check transparency and the costs of your plan.","category":"Swords","order":56,"observation":"A figure carries swords away, leaving others behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S07","reverseAction":"If independent arrangements affect others, agree on which information must be shared."},{"id":57,"name":"Eight of Swords","en":"EIGHT OF SWORDS","roman":"8","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Feeling restricted, limitations and possible room to act","x":50,"y":50,"scene":true}],"theme":"Feeling restricted, limitations and possible room to act","reverse":"Recognizing options or restrictions that remain","action":"Separate real obstacles from untested assumptions.","category":"Swords","order":57,"observation":"A bound, blindfolded figure is surrounded by swords.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S08","reverseAction":"Finding one form of support does not mean every obstacle was imagined."},{"id":58,"name":"Nine of Swords","en":"NINE OF SWORDS","roman":"9","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Worry, repeated thinking and pressure","x":50,"y":50,"scene":true}],"theme":"Worry, repeated thinking and pressure","reverse":"Easing worries or difficulty expressing them","action":"Separate events that happened from worries about them.","category":"Swords","order":58,"observation":"A figure covers their face in bed, with swords arranged behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S09","reverseAction":"A new fact may reduce pressure; leave what is still unknown uncertain."},{"id":59,"name":"Ten of Swords","en":"TEN OF SWORDS","roman":"10","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"A difficulty reaching its limit and ending","x":50,"y":50,"scene":true}],"theme":"A difficulty reaching its limit and ending","reverse":"Recovery after an ending or difficulty accepting closure","action":"Identify what cannot continue and ask for support.","category":"Swords","order":59,"observation":"A fallen figure has swords in their back, with light in the distance.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S10","reverseAction":"A plan ending calls for recovery and reflection; the image does not imply physical harm in real life."},{"id":60,"name":"Page of Swords","en":"PAGE OF SWORDS","roman":"11","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Questioning, checking facts and staying alert","x":50,"y":50,"scene":true}],"theme":"Questioning, checking facts and staying alert","reverse":"Insufficient verification or excessive vigilance","action":"Check one key fact.","category":"Swords","order":60,"observation":"A young figure holds a sword with both hands and looks aside, with clouds and uneven ground behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S11","reverseAction":"Verify a source before forwarding an unconfirmed message."},{"id":61,"name":"Knight of Swords","en":"KNIGHT OF SWORDS","roman":"12","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Advancing a view quickly and defending a position","x":50,"y":50,"scene":true}],"theme":"Advancing a view quickly and defending a position","reverse":"Disorganized action or speaking too quickly","action":"State a view briefly and allow time for a response.","category":"Swords","order":61,"observation":"A rider raises a sword as the horse runs forward, with slanting clouds and trees behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S12","reverseAction":"Separate a claim from its evidence if facts were missed while defending a position."},{"id":62,"name":"Queen of Swords","en":"QUEEN OF SWORDS","roman":"13","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Clear expression, independent judgment and boundaries","x":50,"y":50,"scene":true}],"theme":"Clear expression, independent judgment and boundaries","reverse":"Blocked expression or overly harsh boundaries","action":"Define acceptable and unacceptable agreements.","category":"Swords","order":62,"observation":"A queen sits on a throne, holding a sword upright in one hand and extending the other.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S13","reverseAction":"Replace aggressive wording with a specific request when explaining a need."},{"id":63,"name":"King of Swords","en":"KING OF SWORDS","roman":"14","archetype":"thinker","emotion":"clear-headed","symbols":[{"name":"Card scene","meaning":"Organizing through reasoning, rules and judgment","x":50,"y":50,"scene":true}],"theme":"Organizing through reasoning, rules and judgment","reverse":"Unbalanced judgment or rules detached from facts","action":"Set out evidence, criteria and responsibilities.","category":"Swords","order":63,"observation":"A king sits on a throne holding an unsheathed sword.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-S14","reverseAction":"Check whether a rule applies to the known conditions rather than citing it alone."},{"id":64,"name":"Ace of Pentacles","en":"ACE OF PENTACLES","roman":"1","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Practical opportunity, resources and beginnings","x":50,"y":50,"scene":true}],"theme":"Practical opportunity, resources and beginnings","reverse":"An unrealized opportunity or missing preparation","action":"Check an opportunity's costs and first step.","category":"Pentacles","order":64,"observation":"A hand emerging from a cloud holds a pentacle above a garden path.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P01","reverseAction":"Confirm time and budget before committing to an invitation."},{"id":65,"name":"Two of Pentacles","en":"TWO OF PENTACLES","roman":"2","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Coordination, change and everyday balance","x":50,"y":50,"scene":true}],"theme":"Coordination, change and everyday balance","reverse":"Uneven coordination or too many simultaneous tasks","action":"Prioritize time and spending.","category":"Pentacles","order":65,"observation":"A figure holds two pentacles connected by a looping ribbon.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P02","reverseAction":"When two tasks repeatedly conflict, choose a priority rather than demanding more speed."},{"id":66,"name":"Three of Pentacles","en":"THREE OF PENTACLES","roman":"3","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Skill, teamwork and professional feedback","x":50,"y":50,"scene":true}],"theme":"Skill, teamwork and professional feedback","reverse":"Limited collaborative feedback or skills needing practice","action":"Ask a companion to review one result.","category":"Pentacles","order":66,"observation":"A figure works with tools on a platform as two others face them, one holding a document; three pentacles appear above.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P03","reverseAction":"Participation still needs clear roles, completion criteria and deliverables."},{"id":67,"name":"Four of Pentacles","en":"FOUR OF PENTACLES","roman":"4","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Protection, control and keeping resources","x":50,"y":50,"scene":true}],"theme":"Protection, control and keeping resources","reverse":"Difficulty letting go or adjusting resource control","action":"Distinguish essential reserves from holding too tightly.","category":"Pentacles","order":67,"observation":"A figure holds pentacles tightly with hands, feet and head.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P04","reverseAction":"Keeping reserves can be reasonable; question excessive control when it prevents necessary spending."},{"id":68,"name":"Five of Pentacles","en":"FIVE OF PENTACLES","roman":"5","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Shortage, difficulty and seeking support","x":50,"y":50,"scene":true}],"theme":"Shortage, difficulty and seeking support","reverse":"Beginning to receive help or needs still unanswered","action":"List practical forms of help you can request.","category":"Pentacles","order":68,"observation":"Two people walk through snow beneath a window displaying pentacles.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P05","reverseAction":"Partial help after a request does not mean every shortage has been solved."},{"id":69,"name":"Six of Pentacles","en":"SIX OF PENTACLES","roman":"6","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Giving, receiving and distribution","x":50,"y":50,"scene":true}],"theme":"Giving, receiving and distribution","reverse":"Unequal giving and receiving or unclear exchange terms","action":"Confirm the conditions and fairness of help.","category":"Pentacles","order":69,"observation":"A figure weighs and distributes coins to kneeling people.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P06","reverseAction":"Ask about responsibilities and scope if help comes with unspecified expectations."},{"id":70,"name":"Seven of Pentacles","en":"SEVEN OF PENTACLES","roman":"7","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Assessment, waiting and returns on effort","x":50,"y":50,"scene":true}],"theme":"Assessment, waiting and returns on effort","reverse":"Waiting without review or reconsidering investment","action":"Set a check-in to decide whether to continue or adjust.","category":"Pentacles","order":70,"observation":"A figure leans on a tool and looks at growing pentacles.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P07","reverseAction":"Choose a review measure if effort continues without checking its effect."},{"id":71,"name":"Eight of Pentacles","en":"EIGHT OF PENTACLES","roman":"8","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Practice, craft and gradual improvement","x":50,"y":50,"scene":true}],"theme":"Practice, craft and gradual improvement","reverse":"Blocked practice quality or repetition without progress","action":"Practice one skill and ask for feedback.","category":"Pentacles","order":71,"observation":"A seated figure uses tools on a pentacle, with others arranged nearby and buildings in the distance.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P08","reverseAction":"If repeated attempts are not compared, add a round of feedback."},{"id":72,"name":"Nine of Pentacles","en":"NINE OF PENTACLES","roman":"9","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Independence, achievement and quality of life","x":50,"y":50,"scene":true}],"theme":"Independence, achievement and quality of life","reverse":"Unstable independence or an imbalance between results and effort","action":"Protect the skills and rhythm you have developed.","category":"Pentacles","order":72,"observation":"A figure stands in a garden with a bird on their hand.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P09","reverseAction":"Check sustainability if a good lifestyle comes with exhausted energy or budget."},{"id":73,"name":"Ten of Pentacles","en":"TEN OF PENTACLES","roman":"10","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Long-term accumulation, shared resources and inheritance","x":50,"y":50,"scene":true}],"theme":"Long-term accumulation, shared resources and inheritance","reverse":"Unclear shared resources or a long-term plan needing revision","action":"Discuss lasting support and long-term arrangements.","category":"Pentacles","order":73,"observation":"Several generations of people appear with dogs and buildings.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P10","reverseAction":"Clarify ownership and responsibilities if family members understand resource use differently."},{"id":74,"name":"Page of Pentacles","en":"PAGE OF PENTACLES","roman":"11","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Learning, focus and practical resources","x":50,"y":50,"scene":true}],"theme":"Learning, focus and practical resources","reverse":"Preparation without practice or scattered attention","action":"Practice one usable skill.","category":"Pentacles","order":74,"observation":"A young figure stands holding a pentacle in both hands and looking at it.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P11","reverseAction":"If you have collected many materials without practicing, choose one small task you can finish."},{"id":75,"name":"Knight of Pentacles","en":"KNIGHT OF PENTACLES","roman":"12","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Reliable pacing and consistent execution","x":50,"y":50,"scene":true}],"theme":"Reliable pacing and consistent execution","reverse":"Rigid execution or stalled progress","action":"Complete a task at a steady pace.","category":"Pentacles","order":75,"observation":"A rider sits on a horse holding a pentacle, with fields behind.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P12","reverseAction":"Adjust a familiar plan if conditions changed rather than persisting for its own sake."},{"id":76,"name":"Queen of Pentacles","en":"QUEEN OF PENTACLES","roman":"13","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Everyday care and practical resource planning","x":50,"y":50,"scene":true}],"theme":"Everyday care and practical resource planning","reverse":"Exhaustion from care or insufficient practical arrangements","action":"Arrange practical care while keeping resources for yourself.","category":"Pentacles","order":76,"observation":"A queen sits on a throne among plants, holding a pentacle with both hands.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P13","reverseAction":"If caring for many people leaves no time for yourself, redistribute the work."},{"id":77,"name":"King of Pentacles","en":"KING OF PENTACLES","roman":"14","archetype":"practitioner","emotion":"grounded","symbols":[{"name":"Card scene","meaning":"Sustained management, resources and tangible results","x":50,"y":50,"scene":true}],"theme":"Sustained management, resources and tangible results","reverse":"Unsustained management or excessive resource control","action":"Check ongoing investment and the conditions for returns.","category":"Pentacles","order":77,"observation":"A king sits on a throne with bull-head decorations, holding a short scepter and a pentacle.","learningSource":"Paijian 78-card learning library (modern teaching layer)","sourceId":"RWS-P14","reverseAction":"Review long-term arrangements if short-term results overlook maintenance and companions' needs."}];
